-- +goose up

-- Where the ambient NPC taxis (modules/npcs.pwn) stand still for at least
-- 5s along their recorded routes: 182 stops over 16 taxis. Generated
-- from npcmodes/recordings/NPC_TRACK_TAXI_*.rec by utils/taxistops/taxi_stops.py;
-- rerun it rather than editing the rows by hand.
--
-- taxi_tracks holds how long each recording segment plays, so the gamemode
-- can tell where in its loop a taxi is. A stop is at time_ms into segment
-- segment_no and lasts duration_ms, which may run on into the next segment.
-- rot is the cab's heading there. modules/taxistop.pwn pairs every stop
-- with the nearest commercial property when it loads them.

CREATE TABLE IF NOT EXISTS "taxi_tracks" (
	"taxi_no"	INTEGER NOT NULL,
	"segment_no"	INTEGER NOT NULL,
	"duration_ms"	INTEGER NOT NULL,
	PRIMARY KEY("taxi_no","segment_no")
);

CREATE TABLE IF NOT EXISTS "taxi_stops" (
	"id"	INTEGER,
	"taxi_no"	INTEGER NOT NULL,
	"segment_no"	INTEGER NOT NULL,
	"time_ms"	INTEGER NOT NULL,
	"duration_ms"	INTEGER NOT NULL,
	"x"	REAL NOT NULL,
	"y"	REAL NOT NULL,
	"z"	REAL NOT NULL,
	"rot"	REAL NOT NULL,
	PRIMARY KEY("id" AUTOINCREMENT),
	FOREIGN KEY("taxi_no","segment_no") REFERENCES "taxi_tracks"("taxi_no","segment_no")
);



-- +goose Down
DROP TABLE IF EXISTS "taxi_stops";
DROP TABLE IF EXISTS "taxi_tracks";
